#pragma once#include "GraphObjPoints.h"#include <list>#include <string>#include <map>#include <vector>enum ESideType{  estUnknown= 0,  estLeft = 0x01,  estUp =   0x02,  estRight= 0x04,  estDown = 0x08,};typedef std::list<tGraphObjPointsPtr_> tGraphObjsCont_;struct STextRec {  POINT ptOut;  std::string text;  UINT iMode;};typedef std::list<STextRec> tTextCont_;///struct IPinConnection : ref_counted{  tGraphObjPointsPtr_ ptrObjG;  CPoint pt;  ESideType bLeftUp;  std::string szIndexName;  tGraphObjPointsPtr_ next;  tGraphObjPointsPtr_ prevs[2];  bool operator<( const IPinConnection &thr )  {    if( bLeftUp&(estLeft|estRight) )    {      if( pt.y > thr.pt.y )        return true;      return false;    }    if( pt.x < thr.pt.x )      return true;    return false;  }  virtual eSubObjectTypes GetSubTypeFromPrevs() = 0;};typedef TIntrusivePtr<IPinConnection> tPinConnectionPtr;struct SPinConnection : public TIntrusivePtrImpl<IPinConnection>{  SPinConnection()  {    bLeftUp = estUnknown;    pt.SetPoint( 0, 0 );  }  SPinConnection( const tGraphObjsCont_::iterator &it )  {    ptrObjG = *it;    bLeftUp = estUnknown;  }  SPinConnection( const tGraphObjsCont_::iterator &it, const POINT &_pt )  {    ptrObjG = *it;    pt = _pt;    bLeftUp = estUnknown;  }  SPinConnection( const tGraphObjsCont_::iterator &it, const POINT &_pt, ESideType blu )  {    ptrObjG = *it;    pt = _pt;    bLeftUp = blu;  }  virtual eSubObjectTypes GetSubTypeFromPrevs()  {    eSubObjectTypes type = esotUnknown;    if( prevs[1] )      type = prevs[1]->GetSubObjectType();    if( prevs[0] )    {      eSubObjectTypes t = prevs[0]->GetSubObjectType();      if( esotUnknown==type )        type = t;      ASSD( type==t );    }    return type;  }};typedef std::vector<tPinConnectionPtr> tConInfoCont_;///struct IElementOutsConnection : ref_counted{  IElementOutsConnection() : dataType( esotUnknown )  {}  tGraphObjPointsPtr_ blockOut;  tGraphObjPointsPtr_ pinOut;  tConInfoCont_ dests;  eSubObjectTypes dataType;};typedef TIntrusivePtr<IElementOutsConnection> tElementOutsConnectionPtr;struct SElementOutsConnection : public TIntrusivePtrImpl<IElementOutsConnection>{};typedef std::list<tElementOutsConnectionPtr> tAllConnectionsCont_;struct SBlockOutConnection{  tElementOutsConnectionPtr ptrConnection;  tPinConnectionPtr pinOut;};typedef std::list<SBlockOutConnection> tBlockOutConnectionsCont_;struct IBlocksWithPins : ref_counted{  IBlocksWithPins()    : leftInCount( 0 )    , upInCount( 0 )    , rightOutCount( 0 )    , downOutCount( 0 )    , ExecOrder( 0 )  {  }  tGraphObjPointsPtr_ graphBlock;  tConInfoCont_ pins;  tConInfoCont_ pinsLeft, pinsUp, pinsRight, pinsDown;  int leftInCount, upInCount, rightOutCount, downOutCount;  tBlockOutConnectionsCont_ destConnects;  int ExecOrder;  std::string szBlockType, szDataType;  tAllConnectionsCont_ outConnections;  virtual tPinConnectionPtr GetOutPinInfo( int id ) = 0;};typedef TIntrusivePtr<IBlocksWithPins> tBlocksWithPinsPtr;struct SBlocksWithPins : TIntrusivePtrImpl<IBlocksWithPins>{  SBlocksWithPins( tGraphObjPointsPtr_ &ptr )  {    graphBlock = ptr;  }  virtual tPinConnectionPtr GetOutPinInfo( int id )  {    for( tBlockOutConnectionsCont_::iterator it=destConnects.begin(), end(destConnects.end()); it!=end; ++it )    {      SBlockOutConnection &big = *it;      if( big.ptrConnection->pinOut->GetID()!=id )        continue;      return big.pinOut;    }    ASSD(0);    return tPinConnectionPtr();  }};typedef std::vector<tBlocksWithPinsPtr> tFullBlocksCont_;struct SWorkSheet{  std::string title, description, index;  void clear()  {    title.clear();    description.clear();    index.clear();  }};struct SInOutConnections{  tAllConnectionsCont_ inputs;  tAllConnectionsCont_ outputs;};typedef std::map<int, SInOutConnections> tElByExecOrder_;